#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20};

    // Successful insertion
    auto [it_new, success_new] = s.insert(30);
    std::cout << "New insertion success: " << success_new << std::endl;

    // Failed insertion (duplicate key)
    auto [it_fail, success_fail] = s.insert(20);
    std::cout << "Duplicate insertion success: " << success_fail << std::endl;

    // it_fail points to the existing '20'
    std::cout << "Iterator points to: " << *it_fail << std::endl;
}
